(() => {
  'use strict';
  const D = window.ROADMAP_DATA;
  const KEY = 'first-rupee-roadmap-v1';
  const STEPS = ['learn','sample','buyers','offer','scope','deliver','paid','repeat'];
  const VIEWS = {today:'Start here',routes:'Find your route',playbook:'Step-by-step playbook',ladder:'Money & deadlines',roadmap:'Your 90-day map',india:'India: money, tax & scams',evidence:'Evidence & resources'};
  const main = document.querySelector('#main');
  const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const rupee = value => new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',minimumFractionDigits:Number.isInteger(value)?0:2,maximumFractionDigits:2}).format(value);
  const num = value => new Intl.NumberFormat('en-IN',{maximumFractionDigits:1}).format(value);
  const route = id => D.routes.find(r => r.id === id);
  const source = id => D.sources.find(s => s.id === id);
  const sourceLink = id => {const s=source(id); return s ? `<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)}</a>` : '';};
  const list = items => `<ul>${items.map(i=>`<li>${esc(i)}</li>`).join('')}</ul>`;
  const option = (value,label,current) => `<option value="${esc(value)}"${String(current)===String(value)?' selected':''}>${esc(label)}</option>`;
  const fresh = () => ({version:1,activeRoute:'tutoring',goal:{target:1500,days:30,hours:2},checklists:{},milestones:{},ledger:[],calc:{price:1500,fee:0,cost:0,delivery:14,revision:1,acquisition:2}});
  function validate(input) {
    if (!input || input.version!==1 || !route(input.activeRoute)) throw new Error('This is not a compatible First₹ progress file.');
    const inRange = (n,min,max) => typeof n==='number' && Number.isFinite(n) && n>=min && n<=max;
    if (!input.goal || !inRange(input.goal.target,1,1000000) || !inRange(input.goal.days,1,365) || !inRange(input.goal.hours,.25,8)) throw new Error('The goal values are invalid.');
    if (!input.calc || !inRange(input.calc.price,.01,1000000) || !inRange(input.calc.fee,0,100) || !inRange(input.calc.cost,0,1000000) || !inRange(input.calc.delivery,.05,1000) || !inRange(input.calc.revision,0,1000) || !inRange(input.calc.acquisition,0,1000)) throw new Error('The calculator values are invalid.');
    const safe = fresh(); safe.activeRoute=input.activeRoute; safe.goal={target:input.goal.target,days:input.goal.days,hours:input.goal.hours};
    for (const k of Object.keys(safe.calc)) safe.calc[k]=input.calc[k];
    if (!input.checklists || typeof input.checklists!=='object' || Array.isArray(input.checklists)) throw new Error('The checklist is invalid.');
    for (const r of D.routes) {
      if (input.checklists[r.id]) {safe.checklists[r.id]={}; for (const k of STEPS) if (input.checklists[r.id][k]===true) safe.checklists[r.id][k]=true;}
    }
    if (!input.milestones || typeof input.milestones!=='object') throw new Error('The milestone checklist is invalid.');
    D.phases.forEach((p,i)=>p.tasks.forEach((t,j)=>{const k=`${i}-${j}`; if(input.milestones[k]===true)safe.milestones[k]=true;}));
    if (!Array.isArray(input.ledger) || input.ledger.length>500) throw new Error('The income log is invalid or too large.');
    for (const entry of input.ledger) {
      if (!entry || typeof entry.id!=='string' || entry.id.length>100 || typeof entry.label!=='string' || entry.label.length>120 || !inRange(entry.amount,.01,1000000) || !inRange(entry.cost,0,1000000) || !inRange(entry.hours,.05,1000) || typeof entry.date!=='string' || !/^\d{4}-\d{2}-\d{2}$/.test(entry.date)) throw new Error('An income entry is invalid.');
      safe.ledger.push({id:entry.id,label:entry.label,amount:entry.amount,cost:entry.cost,hours:entry.hours,date:entry.date});
    }
    return safe;
  }
  let state=fresh(), storageAvailable=true, loadWarning='';
  try { const raw=localStorage.getItem(KEY); if(raw)state=validate(JSON.parse(raw)); } catch {loadWarning='Saved progress could not be read. This session starts with a fresh plan; your old stored file has not been erased.';}
  let selectedRoute=state.activeRoute, category='All', query='', toastTimer;
  function save() {try {localStorage.setItem(KEY,JSON.stringify(state));storageAvailable=true;} catch {storageAvailable=false; toast('This browser could not save progress. Export a backup before leaving.');}}
  function toast(message) {const el=document.querySelector('#toast'); el.textContent=message;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),5000);}
  function complete(id,key) {return !!state.checklists[id]?.[key];}
  function completed(id) {return STEPS.filter(k=>complete(id,k)).length;}
  function toggleTask(id,key,value) {if(!route(id)||!STEPS.includes(key)||typeof value!=='boolean')throw new Error('Invalid route checklist change.'); if(!state.checklists[id])state.checklists[id]={};state.checklists[id][key]=value;save();}
  function setGoal(goal) {const merged={...state.goal,...goal}; if(!Number.isFinite(merged.target)||merged.target<1||merged.target>1000000||!Number.isFinite(merged.days)||merged.days<1||merged.days>365||!Number.isFinite(merged.hours)||merged.hours<.25||merged.hours>8)throw new Error('Choose a valid goal, 1–365 days and 0.25–8 hours per day.');state.goal=merged;save();}
  const net = () => state.ledger.reduce((total,e)=>total+e.amount-e.cost,0);
  const logHours = () => state.ledger.reduce((total,e)=>total+e.hours,0);
  const heading = (eyebrow,title,description,extra='') => `<div class="page-intro"><div><div class="eyebrow">${esc(eyebrow)}</div><h1>${esc(title)}</h1><p>${esc(description)}</p></div>${extra}</div>`;
  function ring(percent) {const p=Math.max(0,Math.min(100,percent));return `<div class="ring" role="img" aria-label="${Math.round(p)} percent of checklist complete"><svg viewBox="0 0 90 90" aria-hidden="true"><circle cx="45" cy="45" r="37" fill="none" stroke="#e8edf6" stroke-width="7"/><circle cx="45" cy="45" r="37" fill="none" stroke="#167c5d" stroke-width="7" stroke-linecap="round" stroke-dasharray="${p*2.325} 232.5"/></svg><span class="ring-label">${Math.round(p)}%</span></div>`;}
  function goalControls() {
    const targets=[100,500,1000,2000,5000,10000,20000,50000,100000];if(!targets.includes(state.goal.target))targets.push(state.goal.target);targets.sort((a,b)=>a-b);
    const days=[1,5,7,14,30,90];if(!days.includes(state.goal.days))days.push(state.goal.days);days.sort((a,b)=>a-b);
    const hours=[1,2,3,4];if(!hours.includes(state.goal.hours))hours.push(state.goal.hours);hours.sort((a,b)=>a-b);
    return `<div class="card controls"><div><label for="goal-target">Net earning target · INR</label><select id="goal-target" data-goal="target">${targets.map(n=>option(n,rupee(n),state.goal.target)).join('')}</select></div><div><label for="goal-days">Time to try</label><select id="goal-days" data-goal="days">${days.map(n=>option(n,n===1?'Today · 1 day':n===90?'3 months · 90 days':`${n} days`,state.goal.days)).join('')}</select></div><div><label for="goal-hours">Hours available per day</label><select id="goal-hours" data-goal="hours">${hours.map(n=>option(n,`${n} hour${n===1?'':'s'} / day`,state.goal.hours)).join('')}</select></div></div>`;
  }
  function stepContent(r) {
    return [
      {key:'learn',title:'Learn only what this offer needs',time:r.learn,body:`<p><strong>Skills:</strong> ${esc(r.skills.join(', '))}.</p><p><strong>Tools:</strong> ${esc(r.tools)}.</p>${list(r.learnSteps)}<div class="resource-links">${r.resources.map(sourceLink).join('')}</div>`,output:'You can perform the specific operations required by the practice brief. Reading a tutorial alone does not complete this step.'},
      {key:'sample',title:'Make a sample and pass the readiness test',time:'Until every check passes',body:`<div class="sample-box">${esc(r.practice)}</div><div class="pass-gate"><h3>Pass all of these before selling</h3>${list(r.gate)}</div><p class="subtle">Ask a friend to check the output. Label unpaid work “Concept sample”. If you cannot explain or reproduce it, practise more or choose a simpler offer.</p><button class="button small secondary" data-action="download-brief" data-route="${r.id}">Download practice brief</button>`,output:'A usable sample, an honest before/after comparison and a passed readiness test.'},
      {key:'buyers',title:'Find ten reachable people with this need',time:'30–60 min research',body:`${list(r.buyers)}<p>Create columns: name/business, specific need, public source or warm connection, date approached, reply, next step. Do not collect private contact data. A person with a current need is more useful than a hundred random contacts.</p><button class="button small secondary" data-action="download-prospects">Download prospect sheet</button>`,output:'Ten relevant prospects and a one-sentence reason each might need the offer. No messages sent automatically.'},
      {key:'offer',title:'Make five personal, paid-trial offers',time:'30–60 min + reply time',body:`<p>Start with warm contacts. Ask permission to show your sample. Personalise the bracketed parts; do not blast a copied pitch. A free conversation is enough—do not offer a complete unpaid job.</p>${scriptBox(r,'english')}${scriptBox(r,'telugu')}<p class="subtle">Follow up once after 2–3 days if relevant. A refusal is useful information; stop if they ask. If twenty well-matched approaches produce no interest, change the audience or offer before sending more.</p>`,output:'Five genuine approaches recorded with reply status. A buyer is still not guaranteed.'},
      {key:'scope',title:'Agree the exact work, fee and payment',time:'15–30 min once interested',body:`<p><strong>Your starter scope:</strong> ${esc(r.scope)}</p><p><strong>Starting price:</strong> ${rupee(r.price)}. A starting offer for a beginner in India—check what others charge locally and adjust. Ask for the following before promising a deadline:</p>${list(r.inputs)}<p>Write: deliverables, input limits, deadline after inputs arrive, one consolidated revision, fee, payment date and acceptance test. For a small warm-contact job, agree payment on approval. For unfamiliar clients or larger work, use an agreed deposit or funded milestone. A deposit is not completed-job income.</p><p>On Upwork/Fiverr, keep the work and payment in the platform’s required process. Include fees and clearance time.</p><button class="button small secondary" data-action="download-quote" data-route="${r.id}">Download scope & quote</button>`,output:'The buyer explicitly agrees the written scope, fee and deadline. Do not count a conversation as a sale.'},
      {key:'deliver',title:'Deliver and check the promised output',time:`About ${num(r.hours)} delivery hours; estimate`,body:`${list(r.delivery)}<p>Use a simple folder: 01-input, 02-working, 03-final. Keep private client files out of a public portfolio. Tell the client what is ready, what changed and how to request the included revision.</p><div class="notice amber">${esc(r.risk)}</div>`,output:'The agreed files or system, your quality checks and a clear handover. Revision and acquisition time are additional.'},
      {key:'paid',title:'Get approval, receive money and record it',time:'Payment timing varies',body:`<p>Ask the buyer to confirm the work meets the agreed scope. Send the final agreed amount and payment method. Check your own payment app or bank for receipt; a screenshot or promise is not cash received.</p><p>For a warm contact, an agreed UPI transfer may be practical. Receiving money does not require sharing an OTP or entering a PIN at someone else’s request. If a payment is overdue, send a calm reminder with the agreed terms.</p><p>Only log completed work and money actually received. Subtract fees, job costs and any refund. Use an anonymous job label; the log stays in this browser.</p><button class="button small" data-action="go" data-view="ladder" data-scroll="income-log">Open received-income log</button>`,output:'A completed, paid job and an accurate net-income entry. Checking this box does not create an income entry.'},
      {key:'repeat',title:'Use the result to earn the next job',time:'15–30 min',body:`<p>${esc(r.repeat)}</p><p>Ask: “Was the output useful? What would you change? May I show an anonymised sample or ask one person who needs this?” Keep the answer honest. Calculate all hours, including learning, messaging and revisions, before expanding.</p><p>If the first buyer is not satisfied, fix the agreed issue before requesting a testimonial. Do not invent reviews or present concept samples as client results.</p>`,output:'A useful piece of feedback, a permission-based sample or a referral—and a decision to repeat, improve or stop.'}
    ];
  }
  function message(r,language) {
    if(language==='telugu'&&r.messageTe)return r.messageTe;
    if(language!=='telugu'&&r.messageEn)return r.messageEn;
    if(language==='telugu')return `Hi [పేరు], [మీ అవసరాన్ని ఒక వాక్యంలో చెప్పండి]. నేను ${r.name} పని చేయగలను. ఇది నా concept sample: [లింక్]. మొదటి చిన్న పని ₹${r.price}కి, ముందుగా scope మరియు deadline ఒప్పుకుని చేస్తాను. మీకు ఇప్పుడు ఇది ఉపయోగపడుతుందా? ఆసక్తి ఉంటే వివరాలు పంపిస్తాను.`;
    return `Hi [name], I noticed [one specific, relevant need]. I can help with ${r.hook}. Here is a concept sample I made: [link]. My first small job is ₹${r.price}, with the exact scope and deadline agreed before starting. Would that be useful this week? If yes, I can send the details.`;
  }
  function scriptBox(r,language) {return `<div class="script-box"><div class="script-title">${language==='english'?'English · personalise before using':'Telugu + English · edit to sound like you'}</div><p>${esc(message(r,language))}</p><button class="button small secondary" data-action="copy-message" data-route="${r.id}" data-language="${language}">Copy message</button></div>`;}
  function backupBox() {return `<div class="card block-gap"><div class="section-head"><h2>Your plan travels with you</h2><span class="tag grey">Device-local progress</span></div><p class="subtle">Checklists and income entries are saved in this browser, not in an account. Before moving to your new MacBook, export here and import the JSON file there. Do not put private client details in job labels.</p><div class="choice-row no-print"><button class="button small secondary" data-action="export">Export progress</button><button class="button small secondary" data-action="import">Import progress</button></div>${!storageAvailable?'<div class="notice amber">Storage is unavailable. Export before you close this page.</div>':''}</div>`;}
  function todayPage() {
    const r=route(state.activeRoute), steps=stepContent(r), done=completed(r.id), next=steps.find(s=>!complete(r.id,s.key)), amount=net();
    const totalMinutes=Math.round(state.goal.hours*60), budget=[.25,.35,.25,.15].map(x=>Math.round(x*totalMinutes));budget[3]=totalMinutes-budget.slice(0,3).reduce((a,b)=>a+b,0);
    const afterFees=r.price*(1-state.calc.fee/100)-state.calc.cost;
    const starterCount=afterFees>0?Math.ceil(state.goal.target/afterFees):null;
    return heading('FIRST REAL PAYMENT','Make your next small move.',`Start with one useful offer, one sample and a real buyer. ₹100–₹500 is a sensible first milestone. All amounts here are Indian rupees.`, `<a class="button secondary" href="#routes">Compare earning routes</a>`)+goalControls()+
      (loadWarning?`<div class="notice amber">${esc(loadWarning)}</div>`:'')+
      `<div class="grid-two"><section class="card first-action"><div><div class="eyebrow">YOUR NEXT ACTION · ${esc(r.name)}</div><h2>${esc(next?next.title:'Review your paid result and choose the next job')}</h2><p>${esc(next?next.output:'Check actual time, margin and customer feedback. Repeat the offer only if it fits your college schedule.')}</p></div><div class="action-bottom"><a class="button lime" href="#playbook/${r.id}" data-jump-step="${next?.key||'repeat'}">${next?'Open this step':'Review your playbook'}</a><span class="duration">${esc(next?.time||'15-minute review')}</span></div></section><section class="card"><div class="milestone-top"><div><div class="eyebrow">RECEIVED, LESS JOB COSTS</div><div class="big-number">${rupee(amount)}</div><p class="subtle">${state.ledger.length} paid job${state.ledger.length===1?'':'s'} logged · before tax</p></div>${ring(done/8*100)}</div><div class="metric-line"><span>Route checklist</span><strong>${done} / 8 complete</strong></div><div class="progress-track"><span style="width:${Math.max(0,Math.min(100,amount/state.goal.target*100))}%"></span></div><div class="metric-line"><span>Current target</span><strong>${rupee(state.goal.target)} / ${state.goal.days} day${state.goal.days===1?'':'s'}</strong></div><a class="button text" href="#ladder">Check the numbers & log payment</a></section></div>`+
      `<div class="evidence-strip"><span class="tag blue">STARTER EXPERIMENT</span><p><strong>${esc(r.name)} · ${rupee(r.price)} per defined job.</strong> ${starterCount===null?'Your fee/cost settings leave no positive margin.':`At this price, roughly ${starterCount} paid job${starterCount===1?'':'s'} would cover your target using the current fee/cost settings.`} Learning and finding buyers take extra time. This arithmetic is not a sales forecast.</p></div><div class="notice amber"><strong>Before your first payment:</strong> read <a href="#india">India: money, tax &amp; scams</a>—UPI checks, PAN, foreign payments and the Telegram “task job” scam. Never pay money to earn money.</div>`+
      `<div class="equal-two"><section class="card"><div class="section-head"><h2>Your first-job checklist</h2><span class="tag grey">Mark actual progress</span></div>${steps.slice(0,4).map(s=>`<div class="check-row${complete(r.id,s.key)?' complete':''}"><input type="checkbox" id="today-${s.key}" data-task="${s.key}" data-route="${r.id}"${complete(r.id,s.key)?' checked':''}><div class="row-text"><label for="today-${s.key}">${esc(s.title)}</label><p>${esc(s.output)}</p></div></div>`).join('')}<a class="button text" href="#playbook/${r.id}">See all eight steps and instructions</a></section><section class="card"><div class="section-head"><h2>Today’s ${num(state.goal.hours)}-hour budget</h2><span class="tag green">Protect class time</span></div>${['Learn one operation','Make or improve the sample','Research / contact relevant buyers','Check, plan and record'].map((t,i)=>`<div class="metric-line"><span>${t}</span><strong>${budget[i]} min</strong></div>`).join('')}<p class="subtle" style="margin-top:16px">Until you pass the readiness gate, spend the buyer time on research, not promises. During exams, pause new orders and agree realistic deadlines.</p><div class="notice">Your 16 GB laptop is enough to start these small tasks. Use the MacBook when it arrives; you do not need to wait two weeks or buy tools to make a sample.</div></section></div>`+
      `<section class="card block-gap"><div class="section-head"><h2>The path to a paid job</h2><span class="tag blue">Finish the output, then move on</span></div><div class="stage-flow">${steps.map((s,i)=>`<div class="stage${complete(r.id,s.key)?' done':''}"><div class="stage-number">${String(i+1).padStart(2,'0')} ${complete(r.id,s.key)?'· DONE':''}</div><h3>${esc(['Learn the basics','Prove readiness','Find real buyers','Offer a paid trial','Agree the work','Deliver & check','Receive payment','Improve & repeat'][i])}</h3><p>${esc(['Relevant skill only','Honest sample + checks','Ten reachable prospects','Five personal approaches','Scope, price, deadline','QA and handover','Log actual net income','Feedback and referrals'][i])}</p></div>`).join('')}</div><p class="flow-caption">An offer, a deposit and a completed paid job are different milestones. A checked box is not proof of income.</p></section>`+
      `<div class="equal-two"><section class="card"><span class="tag blue">STRONG ENGINEERING</span><h2 style="margin-top:14px">You can choose a deeper route.</h2><p class="subtle">Start with a small fix, a QA report or a CSV utility. Move toward reporting, dashboards and API integrations once you pass the tests. Engineering can raise the value of a job; it also raises the skill and reliability requirements.</p><button class="button small secondary" data-action="filter-engineering">Explore eight engineering playbooks</button></section><section class="card"><span class="tag amber">IF YOU NEED MONEY TODAY</span><h2 style="margin-top:14px">Use skill and trust you already have.</h2><p class="subtle">A small document cleanup, poster or lesson for a warm contact is more plausible than joining a platform and expecting same-day withdrawal. If you have no ready skill or interested buyer, ₹0 today is realistic.</p><a class="button small secondary" href="#ladder">See the target / deadline matrix</a></section></div>`+backupBox();
  }
  function routeCards() {
    const found=D.routes.filter(r=>(category==='All'||r.category===category)&&`${r.name} ${r.summary} ${r.skills.join(' ')}`.toLowerCase().includes(query.toLowerCase()));
    return found.length?found.map(r=>`<article class="card route-card"><div class="card-top"><span class="tag ${r.category==='Engineering'?'blue':r.category==='Quick start'?'green':'grey'}">${esc(r.category)}</span><span class="route-index">${state.activeRoute===r.id?'YOUR ROUTE':String(D.routes.indexOf(r)+1).padStart(2,'0')}</span></div><h3>${esc(r.name)}</h3><p>${esc(r.summary)}</p><div class="route-price">${rupee(r.price)} <span class="subtle">test offer</span></div><div class="skill-tags">${esc(r.skills.join(' · '))}</div><div class="route-meta"><span>Practice: ${esc(r.learn)}</span><span>Delivery: ~${num(r.hours)} h</span></div><a class="button secondary" href="#playbook/${r.id}">Open detailed playbook</a></article>`).join(''):'<div class="card empty">No routes match. Try a broader search or choose All.</div>';
  }
  function routesPage() {return heading('CHOOSE ONE EXPERIMENT',`${D.routes.length} useful ways to start.`,`Creative, teaching, business support and strong engineering. Choose for existing skill, reachable buyers and delivery time—not an impressive income claim.`)+
    `<div class="notice">Prices and practice times are editorial test estimates, not verified earnings. Learning from zero may take much longer. Keep your first offer small and pass its readiness test before selling.</div><div class="route-tools"><div style="width:100%;max-width:420px"><label for="route-search">Search routes or skills</label><input id="route-search" type="search" placeholder="Try Python, tutoring, video, spreadsheet…" value="${esc(query)}"></div><span class="result-count" id="route-count" aria-live="polite"></span></div><div class="filters" role="group" aria-label="Filter earning routes">${['All','Quick start','Creative','Business support','Teaching','Engineering'].map(c=>`<button class="chip${c===category?' active':''}" data-action="filter" data-category="${c}" aria-pressed="${c===category}">${c}</button>`).join('')}</div><div class="routes-grid" id="route-grid">${routeCards()}</div><section class="card block-gap" style="margin-top:23px"><h2>How to choose without getting stuck</h2><div class="decision-flow"><div class="decision-branch"><div class="condition">NEED A FIRST SMALL PAYMENT</div><h3>Start with existing competence</h3><p>Tuition for a school student is the most dependable start in India. Document cleanup or a simple poster for someone you know also needs little new learning.</p></div><div class="decision-branch"><div class="condition">ENJOY DEEP TECHNICAL WORK</div><h3>Choose a testable deliverable</h3><p>QA, a web fix or a CSV utility gives you a smaller first scope. Work toward API and data systems with stronger acceptance tests.</p></div><div class="decision-branch"><div class="condition">WANT RECURRING INCOME</div><h3>Find a repeated customer task</h3><p>Weekly clips, reports, admin or lessons can recur. One satisfied paying client is evidence; a hypothetical subscription is not.</p></div></div></section>`;}
  function playbookPage() {
    const r=route(selectedRoute)||route(state.activeRoute), steps=stepContent(r);
    return heading('LEARN · SELL · DELIVER',r.name,'A small, bounded first offer. Finish each output and check it before marking the step complete.',`<div class="playbook-selector"><label for="route-selector">Read another playbook</label><select id="route-selector">${D.routes.map(x=>option(x.id,x.name,r.id)).join('')}</select></div>`)+
      `<div class="experiment-head"><p>${state.activeRoute===r.id?`<strong>This is your active route.</strong> ${completed(r.id)} of 8 steps checked.`:`You are exploring this route. Your active plan is still <strong>${esc(route(state.activeRoute).name)}</strong>.`}</p>${state.activeRoute!==r.id?`<button class="button small" data-action="use-route" data-route="${r.id}">Make this my route</button>`:'<a class="button small secondary" href="#today">View my current plan</a>'}</div>`+
      `<section class="card offer-card block-gap"><div class="eyebrow">YOUR FIRST TEST OFFER</div><div class="offer-price">${rupee(r.price)}</div><p>${esc(r.scope)}</p><div class="facts"><div class="fact"><small>Skills to practise</small><strong>${esc(r.skills.join(', '))}</strong></div><div class="fact"><small>Practice estimate</small><strong>${esc(r.learn)}</strong></div><div class="fact"><small>Delivery estimate</small><strong>~${num(r.hours)} h + acquisition / revisions</strong></div></div><div class="source-links-inline"><strong>Evidence:</strong>${r.sources.map(sourceLink).join('')}</div><p class="field-hint">The price is a starter experiment, not a claim about what these sources pay. Adjust scope or quote after measuring real work.</p></section>`+
      `<section class="card block-gap">${steps.map((s,i)=>`<article class="playbook-step" id="step-${s.key}"><div class="step-header${complete(r.id,s.key)?' checked':''}"><input type="checkbox" id="task-${r.id}-${s.key}" data-task="${s.key}" data-route="${r.id}"${complete(r.id,s.key)?' checked':''}><h3><label for="task-${r.id}-${s.key}" style="font:inherit;margin:0">${i+1}. ${esc(s.title)}</label></h3><span class="tag grey">${esc(s.time)}</span></div><div class="step-body">${s.body}<div class="output"><strong>Done means:</strong> ${esc(s.output)}</div></div></article>`).join('')}</section>`+backupBox();
  }
  const matrix=[{amount:100,cells:'RRRRRR'},{amount:500,cells:'SRRRRR'},{amount:1000,cells:'SRRRRR'},{amount:2000,cells:'SSRRRR'},{amount:5000,cells:'XSSRRR'},{amount:10000,cells:'XXSSRR'},{amount:20000,cells:'XXXSSR'},{amount:50000,cells:'XXXXSS'},{amount:100000,cells:'XXXXXS'}];
  function calcNumbers() {
    const c=state.calc, kept=c.price*(1-c.fee/100)-c.cost, jobs=kept>0?Math.ceil(state.goal.target/kept):null;
    const budget=state.goal.days*state.goal.hours, perJob=c.delivery+c.revision+c.acquisition, required=jobs===null?null:jobs*perJob;
    return {kept,jobs,budget,perJob,required};
  }
  function calcResult() {
    const x=calcNumbers(), c=state.calc;
    if(x.jobs===null)return `<div class="calc-result"><h3>No positive margin at these settings.</h3><p>Your retained amount is ${rupee(x.kept)} per job. Raise the price, reduce agreed costs or change the offer. More loss-making jobs will not achieve a positive target.</p></div>`;
    const capacity=Math.floor(x.budget/x.perJob), workload=x.required>x.budget;
    return `<div class="calc-result"><div class="eyebrow" style="color:var(--lime)">ARITHMETIC, NOT A SALES FORECAST</div><div class="calc-metrics"><div><strong>${rupee(x.kept)}</strong><span>retained per paid job · before tax</span></div><div><strong>${x.jobs} jobs</strong><span>to cover ${rupee(state.goal.target)}</span></div><div><strong>${num(x.required)} h</strong><span>estimated work / ${num(x.budget)} h available</span></div></div><p class="subtle">${workload?`This exceeds your time budget by ${num(x.required-x.budget)} hours. At most ${capacity} jobs fit the stated assumptions.`:`The workload fits on paper. You still need ${x.jobs} buyers/jobs, timely inputs and payment within ${state.goal.days} days.`} Learning time and platform withdrawal delays are not included.</p></div><div class="capacity-bar" role="img" aria-label="Time per job: ${num(c.delivery)} hours delivery, ${num(c.revision)} revision and ${num(c.acquisition)} finding buyers">${[['delivery','#3158cf'],['revision','#92aae9'],['acquisition','#bfe56d']].map(([k,color])=>`<span style="width:${c[k]/x.perJob*100}%;background:${color}"></span>`).join('')}</div><div class="bar-key"><span style="--bar-color:#3158cf">Delivery</span><span style="--bar-color:#92aae9">Revisions/admin</span><span style="--bar-color:#bfe56d">Finding buyers</span></div><p class="field-hint">No conversion rate is assumed. Acquisition hours are your input and can be far higher. Fixed costs, tax and refunds need separate allowance.</p>`;
  }
  function ladderPage() {
    const labels={R:'Plausible',S:'Stretch',X:'Poor plan'}, cls={R:'r',S:'s',X:'x'};
    const fields=[['price','Price paid per job · ₹',.01,1000000,.01],['fee','Platform/payment fee · %',0,100,.1],['cost','Other direct cost per job · ₹',0,1000000,.01],['delivery','Delivery hours per job',.05,1000,.05],['revision','Revision + admin hours per job',0,1000,.05],['acquisition','Finding-buyer hours per paid job',0,1000,.05]];
    return heading('KEEP THE NUMBERS HONEST','What fits your target and deadline?','For a student starting without clients, savings or an audience. Ratings are judgement calls about feasibility, not probabilities or verified income statistics.')+goalControls()+
      `<section class="card block-gap"><h2>Income × time reality check</h2><p class="subtle">Cumulative net income from completed, paid work within the period. Assume roughly 2–3 available hours a day, existing competence for small jobs and reachable prospects. A 3-month cell means total income across 90 days, not that amount every month.</p><div class="money-table-wrap"><table><caption class="sr-only">Editorial feasibility of net income targets in six time periods</caption><thead><tr><th>Net target · INR</th>${['Today','5 days','1 week','2 weeks','1 month','3 months'].map(s=>`<th scope="col">${s}</th>`).join('')}</tr></thead><tbody>${matrix.map(row=>`<tr><th scope="row">${rupee(row.amount)}</th>${row.cells.split('').map(c=>`<td><span class="heat ${cls[c]}">${labels[c]}</span></td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="legend"><span><span class="heat r">Plausible</span> small competent offer + buyers still required</span><span><span class="heat s">Stretch</span> stronger skills / repeat clients / exceptional sales needed</span><span><span class="heat x">Poor plan</span> do not budget on it from zero</span></div><div class="notice amber">₹1,000–₹20,000 in one day is not a dependable beginner plan. ₹50,000–₹1,00,000 in a short period usually needs an existing pipeline, valuable skill, audience or capital. Collecting an advance for unfinished work does not make it earned income.</div><p class="subtle">If you have only one hour a day, need to learn from zero, or know nobody with the need, downgrade the optimistic cells. ₹0 remains possible in every period. Above ₹1,00,000, use the same unit-economics and capacity tests; larger numbers do not create more buyers.</p></section>`+
      `<section class="card block-gap"><h2>The skill and proof needed at each level</h2><p class="subtle">Example sales models, not forecasts. “Billed” amounts are before fees, costs, refunds and tax. Higher targets require repeat buyers, more value per job or more capacity.</p><div class="level-list">${D.levels.map((l,i)=>`<details class="level-item"${i===0?' open':''}><summary><span class="tag ${i<2?'green':i<4?'blue':'amber'}">${l.target}</span><span>${esc(l.pace)}</span></summary><div class="level-body"><p><strong>Work model:</strong> ${esc(l.model)}</p><p><strong>Skills:</strong> ${esc(l.skill)}</p><p><strong>Proof before moving up:</strong> ${esc(l.proof)}</p><a class="button small secondary" href="#playbook/${l.route}">Read an example playbook</a></div></details>`).join('')}</div></section>`+
      `<section class="card block-gap"><div class="section-head"><h2>Turn a target into actual work</h2><button class="button small secondary" data-action="route-calc">Use my route’s starter numbers</button></div><p class="subtle">Edit the assumptions. For Fiverr, start with 20% in the fee field; for Upwork, enter the fee shown on your actual contract. Add proposal/withdrawal costs to your costs.</p><div class="form-grid">${fields.map(([k,label,min,max,step])=>`<div><label for="calc-${k}">${label}</label><input id="calc-${k}" type="number" min="${min}" max="${max}" step="${step}" data-calc="${k}" value="${state.calc[k]}"></div>`).join('')}</div><div id="calc-output" aria-live="polite">${calcResult()}</div></section>`+
      `<section class="card block-gap" id="income-log"><div class="section-head"><h2>Completed-job income log</h2><span class="tag green">Received money only</span></div><p class="subtle">Log only finished work and payment actually received. Costs include fees, direct expenses and refunds. This is a personal planning log, not a tax/accounting system. Anonymous labels are enough.</p><form id="income-form"><div class="income-form"><div><label for="income-label">Job label</label><input id="income-label" name="label" maxlength="120" placeholder="Document job 1" required></div><div><label for="income-amount">Received · ₹</label><input id="income-amount" name="amount" type="number" min=".01" max="1000000" step=".01" required></div><div><label for="income-cost">Fees / costs · ₹</label><input id="income-cost" name="cost" type="number" min="0" max="1000000" step=".01" value="0" required></div><div><label for="income-hours">All hours spent</label><input id="income-hours" name="hours" type="number" min=".05" max="1000" step=".05" required></div></div><div class="choice-row" style="margin:16px 0"><input id="income-confirm" type="checkbox" required><label for="income-confirm">The work is complete and this money has reached me. It is not an advance or a promise.</label></div><button class="button" type="submit">Add paid job</button></form><div id="income-list">${incomeList()}</div></section>`+
      `<section class="card block-gap"><h2>Real examples of the arithmetic</h2><div class="decision-flow"><div class="decision-branch"><div class="condition">FIRST ₹100</div><h3>One ₹199 document job</h3><p>With no job costs, ₹199 remains before tax. You need an interested buyer, a usable result and a payment—not 100 followers.</p></div><div class="decision-branch"><div class="condition">₹5,000 IN A MONTH</div><h3>Two ₹2,500 repeat packages</h3><p>That is ₹5,000 billed, before costs. At ten hours per package, delivery alone is twenty hours. Winning both clients is the uncertain part.</p></div><div class="decision-branch"><div class="condition">₹20,000 IN A MONTH</div><h3>Four ₹5,000 projects</h3><p>At sixteen delivery hours each, that is sixty-four hours before sales and support. It may exceed a two-hour/day college budget.</p></div></div></section>`;
  }
  function incomeList() {return `<div class="pill-stat"><span class="tag green">Net received: ${rupee(net())}</span><span class="tag grey">${num(logHours())} total hours logged</span>${logHours()>0?`<span class="tag grey">${rupee(net()/logHours())} / logged hour</span>`:''}</div><div class="income-list">${state.ledger.length?state.ledger.slice().reverse().map(e=>`<div class="income-item"><div><strong>${esc(e.label)}</strong><small>${esc(e.date)} · ${num(e.hours)} h · received ${rupee(e.amount)}, costs ${rupee(e.cost)}</small></div><div><strong>${rupee(e.amount-e.cost)} net</strong> <button class="button small secondary" data-action="delete-income" data-id="${esc(e.id)}" aria-label="Remove income entry ${esc(e.label)}">Remove</button></div></div>`).join(''):'<p class="empty">No completed paid jobs logged yet. Your first honest entry matters more than an impressive target.</p>'}</div>`;}
  function flowchart() {return `<div class="flowchart-wrap"><svg class="decision-svg" viewBox="0 0 720 470" role="img" aria-labelledby="flow-title flow-desc"><title id="flow-title">How to move from a sample to a repeat customer</title><desc id="flow-desc">If your sample fails, practise or choose a simpler scope. When ready, approach relevant buyers. If nobody is interested after twenty personal approaches, revise the audience or offer. If interested, agree scope, deliver, receive payment and request feedback.</desc><defs><marker id="flow-arrow" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0 0 L8 4 L0 8" fill="#8799b8"/></marker></defs><g fill="none" stroke="#8799b8" stroke-width="2" marker-end="url(#flow-arrow)"><path d="M355 67 V105"/><path d="M252 140 H204"/><path d="M355 175 V210"/><path d="M252 244 H204"/><path d="M355 279 V321"/><path d="M458 348 H495"/><path d="M591 376 V413 H457"/></g><g font-family="Arial, sans-serif" font-size="14" fill="#647085"><text x="211" y="128">No</text><text x="366" y="196">Yes</text><text x="211" y="232">No</text><text x="366" y="301">Yes</text></g><rect x="248" y="17" width="214" height="50" rx="10" fill="#eef2ff" stroke="#b8c7ed"/><text x="355" y="47" text-anchor="middle" fill="#344a83" font-family="Arial, sans-serif" font-size="16" font-weight="bold">Make one honest sample</text><path d="M355 105 L458 140 L355 175 L252 140 Z" fill="#fff4db" stroke="#dbc18a"/><text x="355" y="145" text-anchor="middle" fill="#735526" font-family="Arial, sans-serif" font-size="15">Pass readiness checks?</text><rect x="20" y="111" width="184" height="58" rx="10" fill="#f5f7fb" stroke="#d8e0ec"/><text x="112" y="136" text-anchor="middle" fill="#43536e" font-family="Arial, sans-serif" font-size="15">Practise or simplify</text><text x="112" y="155" text-anchor="middle" fill="#647085" font-family="Arial, sans-serif" font-size="13">Repeat the sample test</text><path d="M355 210 L458 244 L355 279 L252 244 Z" fill="#fff4db" stroke="#dbc18a"/><text x="355" y="249" text-anchor="middle" fill="#735526" font-family="Arial, sans-serif" font-size="15">Relevant buyer interested?</text><rect x="20" y="213" width="184" height="62" rx="10" fill="#f5f7fb" stroke="#d8e0ec"/><text x="112" y="237" text-anchor="middle" fill="#43536e" font-family="Arial, sans-serif" font-size="15">After 20 approaches,</text><text x="112" y="258" text-anchor="middle" fill="#43536e" font-family="Arial, sans-serif" font-size="15">review audience / offer</text><rect x="248" y="321" width="214" height="55" rx="10" fill="#14213d"/><text x="355" y="345" text-anchor="middle" fill="white" font-family="Arial, sans-serif" font-size="16" font-weight="bold">Agree scope and fee</text><text x="355" y="365" text-anchor="middle" fill="#bdc9df" font-family="Arial, sans-serif" font-size="14">Then deliver and check</text><rect x="495" y="321" width="195" height="55" rx="10" fill="#eaf7f0" stroke="#bedccf"/><text x="592" y="345" text-anchor="middle" fill="#27654c" font-family="Arial, sans-serif" font-size="16" font-weight="bold">Receive payment</text><text x="592" y="365" text-anchor="middle" fill="#27654c" font-family="Arial, sans-serif" font-size="14">Log net completed income</text><rect x="249" y="413" width="208" height="42" rx="10" fill="#eaf7f0" stroke="#bedccf"/><text x="353" y="440" text-anchor="middle" fill="#27654c" font-family="Arial, sans-serif" font-size="16">Feedback, referral, repeat</text></svg></div><p class="flow-caption">The branches are review rules, not measured conversion rates. A buyer can take longer than your chosen deadline.</p>`;}
  function roadmapPage() {return heading('OUTPUTS BEFORE INCOME CLAIMS','Your 90-day working map.','Use the dates as review points. The gates decide whether you move on; completing a week does not guarantee a customer.')+
    `<div class="notice">One main earning experiment plus a small learning block is enough. Keep a second route as a fallback. Do not try all ${D.routes.length} at once.</div><section class="card block-gap"><div class="section-head"><h2>Your decision flow</h2><span class="tag blue">Where to go when a step stalls</span></div>${flowchart()}</section><div class="milestone-map block-gap">${D.phases.map((p,i)=>`<section class="card milestone-card"><div class="milestone-dot">${i+1}</div><div class="period">${esc(p.period.toUpperCase())}</div><h2>${esc(p.title)}</h2><div class="stepchecks">${p.tasks.map((t,j)=>`<div class="compact-check"><input id="milestone-${i}-${j}" type="checkbox" data-milestone="${i}-${j}"${state.milestones[`${i}-${j}`]?' checked':''}><label for="milestone-${i}-${j}">${esc(t)}</label></div>`).join('')}</div><div class="gate-label"><strong>Move-on gate:</strong> ${esc(p.gate)}</div><p class="subtle" style="margin:13px 0 0">${esc(p.note)}</p></section>`).join('')}</div><section class="card block-gap"><h2>A college-compatible week</h2><p class="subtle">An example of twelve focused hours, not a required schedule. Move the blocks around your classes and reduce them during exams. Stay within the hours you entered in the calculator.</p><div class="week-layout">${[['Mon','1 h · learn / practise'],['Tue','1 h · improve sample'],['Wed','1 h · prospect research'],['Thu','2 h · approaches / delivery'],['Fri','1 h · follow-up / checks'],['Sat','3 h · focused delivery'],['Sun','3 h · finish / review']].map(([d,t])=>`<div class="week-day"><strong>${d}</strong><p>${t}</p></div>`).join('')}</div><div class="decision-flow"><div class="decision-branch"><div class="condition">NO REPLIES</div><h3>Review relevance and proof</h3><p>After twenty well-matched personal approaches, ask a neutral person whether the need is real and your sample convincing. Change one variable, then test ten more.</p></div><div class="decision-branch"><div class="condition">INTEREST, NO PURCHASES</div><h3>Reduce uncertainty</h3><p>Ask what blocks the decision. Clarify the small deliverable, turnaround and revision limit. Test a smaller paid scope; do not endlessly cut the price.</p></div><div class="decision-branch"><div class="condition">WORK, BUT LOW MARGIN</div><h3>Fix scope and capacity</h3><p>Measure all time. Quote extra revisions separately, improve speed through practice and raise the next quote only when your proof supports it.</p></div></div></section><section class="card block-gap"><h2>The engineering progression</h2><div class="stage-flow">${[['1','Small fix or QA','Reproduce an issue; test and document the result.','webfix'],['2','Safe data utility','Preserve input, validate records and reconcile output.','csvtool'],['3','Report or dashboard','Test calculations, empty inputs and owner handover.','reporting'],['4','Reliable API workflow','Handle auth, limits, duplicates and recovery.','integration']].map(([n,t,p,id])=>`<div class="stage"><div class="stage-number">LEVEL ${n}</div><h3>${t}</h3><p>${p}</p><a class="button text" href="#playbook/${id}">Read the readiness gate</a></div>`).join('')}</div><p class="flow-caption">This is a skill progression, not a four-week course. You can enter at the level you can demonstrate. Higher-risk engineering may require much longer practice.</p></section>`+backupBox();}
  function evidencePage() {
    const platforms=[['Local tuition & warm contacts','The fastest real money for most students: tuition (₹1,500–₹3,000 per student per month locally) or a small job for someone you know, paid by UPI. No platform fee. Verify the money in your own bank app.','tuition-rates'],['Internshala','Paid work-from-home internships for Indian students. Stipends of a few thousand to ~₹15,000 a month; selection takes weeks. Never pay a fee to be selected.','internshala'],['Upwork','Variable 0–15% fee (often ~10%) plus Connects at US$0.15 each. New Indian profiles are often rejected in crowded categories, and some jobs are restricted by country. Fixed-price review can take 14 days plus a five-day security hold.','upwork-pay'],['Fiverr','You keep 80%; earnings clear in 14 days (7 for top tiers), then withdrawal fees. Getting the first order from India is slow and uncertain.','fiverr'],['Prolific','India is on the supported list, but Prolific describes India as a small participant pool—few studies. Cash out needs £6/US$6 approved and PayPal.','prolific-pool'],['UserTesting','18+, PayPal only, paid about 14 days after a test. Most tests target US/UK users, so expect to be screened out often.','usertesting'],['Outlier','Has run India-only coding roles that accept enrolled CS students (advertised ~US$13.75/hour average). Tasks are not guaranteed. Apply only on the official site—never through an agent.','outlier-india']];
    return heading('WHAT IS DOCUMENTED · WHAT IS ESTIMATED','Evidence you can inspect.','Checked 9 October 2026. Sources can change or disappear. A working business model does not prove a particular student will earn a particular amount.')+
      `<div class="evidence-grid block-gap"><article class="card evidence-card"><span class="tag green">COMPLETED CONTRACTS</span><h2>People have paid for design and editing</h2><p>Indian freelancer profiles show completed jobs in video editing and Canva design. These people have experience and reviews. Their records prove an existing market; they do not prove immediate beginner success.</p><div class="resource-links">${sourceLink('editor-proof')}${sourceLink('design-proof')}</div></article><article class="card evidence-card"><span class="tag blue">CURRENT BUYER REQUESTS</span><h2>Engineering demand has real requirements</h2><p>Recent API and automation requests specify testing, data accuracy and reliability. They support a serious engineering learning path. Posted budgets are requests, not completed earnings.</p><div class="resource-links">${sourceLink('api-job')}${sourceLink('automation-job')}${sourceLink('integration-job')}</div></article><article class="card evidence-card"><span class="tag grey">LISTINGS, NOT VERIFIED BOOKINGS</span><h2>Students advertise tutoring</h2><p>Local maths directories include student tutors and advertised rates. This suggests a plausible way to use existing knowledge, but bookings and take-home earnings are not visible.</p>${sourceLink('tutors')}</article><article class="card evidence-card"><span class="tag amber">EDITORIAL EXPERIMENTS</span><h2>Prices are beginner starting points</h2><p>Tuition and reel prices were checked against Indian listings (₹200–₹300/hour city tuition, ~₹400 per reel). Other prices, practice hours and the feasibility matrix are judgement-based. Actual skill, buyers, competition and scope determine outcomes.</p><div class="resource-links">${sourceLink('tuition-rates')}${sourceLink('reel-rates')}</div></article></div>`+
      `<section class="card block-gap"><h2>Payment timing changes the short-term plan</h2><div class="platform-list">${platforms.map(([name,text,id])=>`<div class="platform-row"><strong>${name}</strong><p>${text}</p>${sourceLink(id)}</div>`).join('')}</div><p class="field-hint">Country eligibility, age/identity requirements, currency conversion, withdrawal methods and fees must be checked for your actual account before relying on a platform.</p></section>`+
      `<section class="card block-gap"><h2>Other models—and when they become useful</h2><p class="subtle">These are part of the map, but most are weaker choices for the first urgent ₹100. Test a small real demand signal before spending weeks building.</p><div class="evidence-grid">${D.later.map(m=>`<article class="evidence-card"><h3>${esc(m.name)}</h3><p><strong>Fit:</strong> ${esc(m.fit)}</p><p><strong>Doable test:</strong> ${esc(m.experiment)}</p><p>${esc(m.why)}</p>${sourceLink(m.source)}</article>`).join('')}</div></section>`+
      `<section class="card block-gap"><h2>Use your AI tools to learn and check work</h2><div class="decision-flow"><div class="decision-branch"><h3>Ask for a practice lesson</h3><p>“Teach me the operation needed for this brief. Give one example and a small exercise. Don’t solve the exercise until I try.” Then create the sample yourself.</p></div><div class="decision-branch"><h3>Ask for a critique</h3><p>“Check this dummy sample against these acceptance criteria. List specific failures and how to reproduce them.” Verify every suggestion.</p></div><div class="decision-branch"><h3>Ask for engineering review</h3><p>“Review this code for malformed inputs, duplicates, auth errors, secrets and rollback. Suggest meaningful tests.” Understand the result before delivering.</p></div></div><div class="notice" style="margin-top:17px">Client data requires permission before uploading to any AI service. Your subscriptions help you produce work; they do not supply clients, replace competence or cover a customer’s API/hosting usage.</div></section>`+
      `<section class="card block-gap"><h2>Free learning and source register</h2><p class="subtle">Open the resources relevant to your chosen route. Each playbook tells you what to practise and how to know you are ready.</p><div class="source-list">${D.sources.map((s,i)=>`<div class="source-item" id="source-${s.id}"><span class="source-n">${String(i+1).padStart(2,'0')}</span><div><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)}</a><p>${esc(s.note)}</p></div></div>`).join('')}</div></section>`+backupBox();
  }
  function indiaPage() {
    const tagClass={scams:'amber',docs:'green',tax:'blue'};
    return heading('MADE FOR INDIA','Money, tax and safety for a student in India.','How you actually receive money here, what tax applies (usually none), and the scams that target students. Checked 9 October 2026—rules change, so confirm on the linked official sites.')+
      `<div class="notice amber"><strong>One rule:</strong> real work never asks you to pay first. If someone wants a deposit, fee or OTP before you earn, stop. Lost money? Call <strong>1930</strong> and report at <a href="https://cybercrime.gov.in/" target="_blank" rel="noopener noreferrer">cybercrime.gov.in</a>.</div>`+
      `<div class="evidence-grid block-gap">${D.india.sections.map(sec=>`<article class="card evidence-card" id="india-${esc(sec.id)}"><span class="tag ${tagClass[sec.id]||'grey'}">${esc(sec.tag.toUpperCase())}</span><h2>${esc(sec.title)}</h2>${list(sec.points)}<div class="resource-links">${sec.sources.map(sourceLink).join('')}</div></article>`).join('')}</div>`+backupBox();
  }
  function currentView() {const bits=location.hash.slice(1).split('/');const view=Object.hasOwn(VIEWS,bits[0])?bits[0]:'today';if(view==='playbook')selectedRoute=route(bits[1])?bits[1]:state.activeRoute;return view;}
  const renderers={today:todayPage,routes:routesPage,playbook:playbookPage,ladder:ladderPage,roadmap:roadmapPage,india:indiaPage,evidence:evidencePage};
  function render({preserve=false}={}) {
    const y=window.scrollY, focused=document.activeElement?.id, view=currentView();
    main.innerHTML=renderers[view]();document.querySelector('#view-label').textContent=VIEWS[view];document.title=`${VIEWS[view]} · First₹`;
    document.querySelectorAll('#navigation [data-view]').forEach(a=>{if(a.dataset.view===view)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
    if(view==='routes')updateRouteResults();
    if(preserve){document.getElementById(focused)?.focus({preventScroll:true});window.scrollTo(0,y);}
  }
  function updateRouteResults() {const grid=document.querySelector('#route-grid');if(!grid)return;grid.innerHTML=routeCards();const count=D.routes.filter(r=>(category==='All'||r.category===category)&&`${r.name} ${r.summary} ${r.skills.join(' ')}`.toLowerCase().includes(query.toLowerCase())).length;document.querySelector('#route-count').textContent=`${count} of ${D.routes.length} routes`;document.querySelectorAll('[data-category]').forEach(b=>{b.classList.toggle('active',b.dataset.category===category);b.setAttribute('aria-pressed',String(b.dataset.category===category));});}
  function download(name,content,type='text/plain;charset=utf-8') {const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  function exportProgress() {download('first-rupee-progress.json',JSON.stringify({...state,exportedAt:new Date().toISOString()},null,2),'application/json');toast('Progress exported. Import this file in the browser on your new laptop.');}
  async function copy(value) {try{await navigator.clipboard.writeText(value);toast('Copied. Personalise the message before using it.');}catch{const text=document.createElement('textarea');text.value=value;text.setAttribute('aria-label','Text to copy');document.body.append(text);text.select();const ok=document.execCommand('copy');text.remove();toast(ok?'Copied. Personalise before using it.':'Copy is unavailable. Select the visible message and copy it manually.');}}
  function setRoute(id) {const r=route(id);if(!r)throw new Error('Unknown route.');state.activeRoute=id;state.calc.price=r.price;state.calc.delivery=r.hours;save();render({preserve:true});toast(`${r.name} is now your active route. Other progress is kept.`);}
  main.addEventListener('click',event=>{
    const b=event.target.closest('[data-action]');if(!b)return;const action=b.dataset.action,r=route(b.dataset.route);
    if(action==='filter'){category=b.dataset.category;updateRouteResults();}
    if(action==='filter-engineering'){category='Engineering';query='';location.hash='routes';}
    if(action==='use-route')setRoute(r.id);
    if(action==='copy-message')copy(message(r,b.dataset.language));
    if(action==='export')exportProgress();
    if(action==='import')document.querySelector('#import-file').click();
    if(action==='go'){location.hash=b.dataset.view;requestAnimationFrame(()=>document.getElementById(b.dataset.scroll)?.scrollIntoView({block:'start'}));}
    if(action==='route-calc'){const active=route(state.activeRoute);state.calc={price:active.price,fee:0,cost:0,delivery:active.hours,revision:.25,acquisition:.5};save();render({preserve:true});toast('Starter assumptions loaded. Change fees, costs and time for your actual job.');}
    if(action==='delete-income'){state.ledger=state.ledger.filter(e=>e.id!==b.dataset.id);save();document.querySelector('#income-list').innerHTML=incomeList();toast('Entry removed.');}
    if(action==='download-brief')download(`${r.id}-practice-brief.txt`,`${r.name}\n\nPRACTICE\n${r.practice}\n\nREADINESS CHECKS\n${r.gate.map(x=>`[ ] ${x}`).join('\n')}\n\nDo not use private client data for practice.`);
    if(action==='download-prospects')download('prospect-tracker.csv','Name or business,Specific current need,Public source or warm connection,Date approached,Reply,Next step\nSample prospect,Replace with a real relevant need,Use a public business source or a warm contact,,,\n','text/csv;charset=utf-8');
    if(action==='download-quote')download(`${r.id}-scope-and-quote.txt`,`${r.name} — scope and quote\n\nBuyer: [name]\nDeliverable: ${r.scope}\nPrice: ₹${r.price} [adjust before sending]\nRequired inputs:\n${r.inputs.map(x=>`- ${x}`).join('\n')}\nDeadline: [date/time, after all inputs arrive]\nIncluded revision: one consolidated request by [date]\nAcceptance checks: [agree before starting]\nPayment method and due date: [agree]\nDeposit/funded milestone, if applicable: [agree; not earned income until work is complete]\nExtra work: separately quoted before starting\nOwnership, permissions and usage: [agree]\nSupport window, if applicable: [agree]\n\nPlease confirm the scope, price and deadline before I start.\n`);
  });
  main.addEventListener('change',event=>{
    const el=event.target;
    if(el.dataset.task){toggleTask(el.dataset.route,el.dataset.task,el.checked);render({preserve:true});}
    if(el.dataset.milestone){state.milestones[el.dataset.milestone]=el.checked;save();}
    if(el.dataset.goal){try{setGoal({[el.dataset.goal]:Number(el.value)});render({preserve:true});}catch(e){toast(e.message);}}
    if(el.id==='route-selector')location.hash=`playbook/${el.value}`;
    if(el.dataset.calc){if(!el.checkValidity()||el.value===''){el.reportValidity();return;}state.calc[el.dataset.calc]=Number(el.value);save();document.querySelector('#calc-output').innerHTML=calcResult();}
  });
  main.addEventListener('input',event=>{if(event.target.id==='route-search'){query=event.target.value;updateRouteResults();}});
  main.addEventListener('submit',event=>{
    if(event.target.id!=='income-form')return;event.preventDefault();const form=event.target;if(!form.reportValidity())return;
    if(state.ledger.length>=500){toast('This log supports 500 entries. Export your history before removing older entries.');return;}
    const data=new FormData(form);const today=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Kolkata',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
    const entry={id:crypto.randomUUID?crypto.randomUUID():`job-${Date.now()}-${Math.random().toString(16).slice(2)}`,label:String(data.get('label')).trim(),amount:Number(data.get('amount')),cost:Number(data.get('cost')),hours:Number(data.get('hours')),date:today};
    if(!entry.label){toast('Use a short job label.');return;}state.ledger.push(entry);save();form.reset();form.querySelector('[name=cost]').value='0';document.querySelector('#income-list').innerHTML=incomeList();toast(`Paid job logged: ${rupee(entry.amount-entry.cost)} after costs.`);
  });
  document.querySelector('#export-progress').addEventListener('click',exportProgress);
  document.querySelector('#import-progress').addEventListener('click',()=>document.querySelector('#import-file').click());
  document.querySelector('#print-plan').addEventListener('click',()=>window.print());
  document.querySelector('#import-file').addEventListener('change',async event=>{
    const file=event.target.files[0];if(!file)return;
    try{if(file.size>1000000)throw new Error('This file is too large. Use a First₹ progress JSON under 1 MB.');const next=validate(JSON.parse(await file.text()));state=next;selectedRoute=state.activeRoute;save();location.hash='today';render();toast('Progress imported. The imported plan replaces this browser’s previous plan.');}catch(e){toast(e.message||'Unable to import this file. Your current plan has been kept.');}finally{event.target.value='';}
  });
  let pendingStep='';
  document.addEventListener('click',event=>{const a=event.target.closest('[data-jump-step]');if(a){pendingStep=a.dataset.jumpStep;if(currentView()==='playbook')document.getElementById(`step-${pendingStep}`)?.scrollIntoView({block:'start'});}});
  window.addEventListener('hashchange',()=>{render();main.focus({preventScroll:true});window.scrollTo(0,0);if(pendingStep){document.getElementById(`step-${pendingStep}`)?.scrollIntoView({block:'start'});pendingStep='';}});
  render();
  /* Optional WebMCP: the same validated state transitions as the visible UI. */
  if (document.modelContext?.registerTool) {
    const json = result => ({content:[{type:'text',text:JSON.stringify(result)}]});
    document.modelContext.registerTool({name:'get_earning_roadmap_progress',title:'Read earning roadmap progress',description:'Read the active route, target, checklist and received net income saved in this browser.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:async()=>json({route:state.activeRoute,goal:state.goal,checklists:state.checklists,netReceived:net(),paidJobs:state.ledger.length})});
    document.modelContext.registerTool({name:'configure_earning_roadmap_goal',title:'Configure earning goal',description:'Set the INR target, time budget in days and hours per day in the current browser. This does not promise earnings.',inputSchema:{type:'object',properties:{target:{type:'number',minimum:1,maximum:1000000},days:{type:'number',minimum:1,maximum:365},hours:{type:'number',minimum:.25,maximum:8}},required:['target','days','hours'],additionalProperties:false},annotations:{readOnlyHint:false},execute:async args=>{if(!args||Object.keys(args).some(k=>!['target','days','hours'].includes(k))||['target','days','hours'].some(k=>typeof args[k]!=='number'))throw new Error('Provide only target, days and hours as numbers.');setGoal(args);render({preserve:true});return json({goal:state.goal});}});
    document.modelContext.registerTool({name:'set_earning_route_checklist',title:'Update route checklist',description:'Mark specified real-progress checklist steps complete or incomplete in the current browser. Does not log income or contact buyers.',inputSchema:{type:'object',properties:{routeId:{type:'string',enum:D.routes.map(r=>r.id)},items:{type:'array',minItems:1,maxItems:8,items:{type:'object',properties:{step:{type:'string',enum:STEPS},completed:{type:'boolean'}},required:['step','completed'],additionalProperties:false}}},required:['routeId','items'],additionalProperties:false},annotations:{readOnlyHint:false},execute:async args=>{if(!args||Object.keys(args).some(k=>!['routeId','items'].includes(k))||!route(args.routeId)||!Array.isArray(args.items)||args.items.length<1||args.items.length>8||args.items.some(x=>!x||Object.keys(x).some(k=>!['step','completed'].includes(k))||!STEPS.includes(x.step)||typeof x.completed!=='boolean'))throw new Error('Provide a valid route and one to eight valid checklist items.');for(const item of args.items)toggleTask(args.routeId,item.step,item.completed);render({preserve:true});return json({route:args.routeId,checklist:state.checklists[args.routeId]});}});
  }
})();
